function cleanText(text) {
  if (!text) return '';
  return text
    .replace(/&quot;|quot;|&#39;|&amp;|&lt;{};|&gt;/g, '')
    .replace(/[^a-zA-Z0-9À-ÿ\s]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const theme = cleanText($json.theme);
const character = cleanText($json.character);
const location = cleanText($json.location);
const videoType = $json.videoType || 'short'; // 'short' ou 'long'

// Hook do universo (personagem + local)
let universeHook = '';
if (character && location) {
  universeHook = ` The main character is ${character}, and the story takes place in ${location}.`;
} else if (character) {
  universeHook = ` The main character is ${character}.`;
} else if (location) {
  universeHook = ` The story takes place in ${location}.`;
}

// Regras de contagem e duração
let wordCountRule = '';
let durationRule = '';
let detailRule = '';

if (videoType === 'long') {
  // Para 7 a 25 minutos de áudio em 1.5x, vamos calcular texto entre ~2000 e 7000 palavras
  wordCountRule = `
- WORD COUNT TARGET: 2000–7000 words.
- This is a story for a 7–25 minute audio at 1.5x speed.
- You MUST write EXTENSIVE and DETAILED text.
- If the output is short, it will fail.`;

  durationRule = '7–25 minutes at 1.5x speed';
  detailRule = `
- Use EXTREME VERBOSITY.
- Describe textures, smells, micro-expressions, thoughts, and surroundings in great detail.
- Expand every scene, every action, every dialogue internally.
- NEVER summarize. Show everything in vivid detail.`;
} else {
  wordCountRule = `
- WORD COUNT: 400–600 words.`;
  durationRule = '1–3 minutes';
  detailRule = '- Fast-paced, high tension, concise scenes.';
}

// Prompt final
const prompt = `
Write a ${videoType.toUpperCase()} story in English about "${theme}".

TARGET DURATION: ${durationRule}
REQUIRED VOLUME: ${wordCountRule}
WRITING STYLE: ${detailRule}

ABSOLUTE RULES (MANDATORY):
1. CLEAN TEXT ONLY: No quotes ("), brackets ([ ]), asterisks (*), or hashtags (#).
2. NO SOUND CUES: Do not write [Tense Music] or [Door Creaks].
3. NO JSON OR TITLES: Output plain text only.
4. FIRST LINE: Must be the Hook only.
5. SECOND LINE: Must be exactly "START_STORY".

${universeHook}
`;

return [{
  json: {
    ...$json,
    prompt,
    videoType,
    theme
  }
}];

