    minWords = 50;
    maxWords = 1200;
    minLength = 300;
    maxLength = 6000;
}

// =========================
// VALIDATION CHECKS
// =========================
const checks = {
    hasTitle: typeof $json.title === 'string' && $json.title.trim().length > 2,
    hasStory: typeof fullText === 'string' && fullText.trim().length > minLength,
    reasonableLength: textLength < maxLength,
    hasHash: typeof $json.storyHash === 'string',
    wordCount: wordCount >= minWords && wordCount <= maxWords
};

