// Nó: Generate English Subtitles

// Puxa o texto diretamente do nó que processou a história
const storyData = $node["Parse Story & Create Hash"].json;
const storyText = storyData.text || storyData.content || "";

// Puxa a duração do áudio (ajuste o nome do nó se for diferente)
const duration = $json.audio_duration_seconds || 60;

const cleanText = storyText
  .replace(/\r/g, "")
  .replace(/\n+/g, " ")
  .replace(/\s+/g, " ")
  .trim();

// Se o texto vier vazio, agora ele vai avisar exatamente qual o problema
if (cleanText.length === 0) {
    throw new Error("O texto da história não foi encontrado. Verifique o nó 'Parse Story & Create Hash'");
}

const words = cleanText.split(/\s+/).filter(w => w.length > 0);
const totalWords = words.length;
const wps = (totalWords / duration) || 2.5;
const avgTimePerWord = 1 / wps;

let srtContent = "";
let currentTimeMs = 0;
let subtitleIndex = 1;
const wordsPerSubtitle = 5;

const formatTime = (ms) => {
  const totalSeconds = Math.floor(ms / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  const milliseconds = Math.floor(ms % 1000);
  return `${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')},${String(milliseconds).padStart(3,'0')}`;
};

for (let i = 0; i < totalWords; i += wordsPerSubtitle) {
  const subtitleWords = words.slice(i, i + wordsPerSubtitle);
  const durationMs = subtitleWords.length * avgTimePerWord * 1000;
  const endTimeMs = currentTimeMs + durationMs;

  srtContent += `${subtitleIndex}\n`;
  srtContent += `${formatTime(currentTimeMs)} --> ${formatTime(endTimeMs)}\n`;
  srtContent += `${subtitleWords.join(" ")}\n\n`;

  currentTimeMs = endTimeMs;
  subtitleIndex++;
}

return [{
  json: {
    ...$json,
    srtText: srtContent
  },
  binary: {
    data: {
      data: Buffer.from(srtContent).toString('base64'),
      fileName: 'legenda.srt',
      mimeType: 'text/plain'
    }
  }
}];

