=# 1. Configura o ambiente para o Node encontrar o Playwright
export NODE_PATH=/usr/local/lib/node_modules:/usr/local/lib/node_modules/n8n/node_modules

# 2. Cria o script JavaScript
cat <<EOF > /tmp/tiktok_upload.js
const { chromium } = require('playwright');
const fs = require('fs');

async function main() {
    const videoPath = process.argv[2];
    const hashtags = process.argv[3];
    const sessionPath = '/home/node/.n8n/session_tiktok.json';

    console.log('🚀 Iniciando Navegador...');
    const browser = await chromium.launch({
        headless: true,
        executablePath: '/usr/bin/chromium-browser',
        args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
    });

    const context = await browser.newContext({
        storageState: fs.existsSync(sessionPath) ? sessionPath : undefined,
        viewport: { width: 1280, height: 720 }
    });

    const page = await context.newPage();

    try {
        console.log('⏳ Acessando TikTok...');
        await page.goto('https://www.tiktok.com/upload', { timeout: 90000, waitUntil: 'networkidle' });

        if (page.url().includes('login')) {
            console.log('❌ Erro: Login necessário! Verifique o session_tiktok.json');
            await browser.close();
            process.exit(1);
        }

        console.log('📤 Enviando vídeo...');
        const inputFile = await page.waitForSelector('input[type=file]', { timeout: 30000 });
        await inputFile.setInputFiles(videoPath);

        console.log('✍️ Inserindo legenda...');
        const caption = await page.waitForSelector('[contenteditable="true"]', { timeout: 30000 });
        await caption.click();
        await page.keyboard.type(hashtags);

        console.log('🚀 Finalizando upload e postando...');
        await page.waitForTimeout(15000); // Tempo para o TikTok processar o vídeo

        const publishBtn = await page.waitForSelector('button:has-text("Post"), button:has-text("Publicar")');
        await publishBtn.click();

        await page.waitForTimeout(5000);
        console.log('✅ Sucesso! Vídeo enviado ao TikTok.');

        await context.storageState({ path: sessionPath });
    } catch (e) {
        console.error('❌ Erro no processo:', e.message);
    } finally {
        await browser.close();
    }
}

main();
EOF

# 3. Executa o script
node /tmp/tiktok_upload.js "{{ $('Extract Video Path').item.json.video_path }}" "{{ $json.hashtags || '#viral #story' }}"

