// Função para limpar o lixo do LLM (Markdown, JSON, aspas extras)
function extractText(rawInput) {
    if (!rawInput) return "";

    // Se for um objeto, tenta pegar o campo text
    if (typeof rawInput === 'object') {
        return rawInput.text || rawInput.content || "";
    }

    let clean = rawInput.toString();

    // 1. Tenta fazer o PARSE se parecer JSON
    try {
        // Remove blocos de código markdown se houver (```json ... ```)
        const jsonCandidate = clean.replace(/```json/g, "").replace(/```/g, "").trim();
        const parsed = JSON.parse(jsonCandidate);
        if (parsed.text) return parsed.text;
    } catch (e) {
        // Não era JSON, segue o jogo
    }

    // 2. Se falhar, limpezas manuais de lixo comum
    return clean
        .replace(/^{"text":\s*"/, "") // Remove inicio JSON manual
        .replace(/"}$/, "")            // Remove fim JSON manual
        .replace(/\\"/g, '"')          // Desescapa aspas
        .trim();
}

// --- PEGA OS DADOS DOS NODES ANTERIORES ---

// Pega a saída bruta do Hook e da História
const hookNode = $('HookGenerator').first().json;
const storyNode = $('StoryGenerator').first().json;

// Aplica a limpeza
