const pixFmtOk = stream.pix_fmt === "yuv420p";

const profile = (stream.profile || "").toLowerCase();
const profileOk = profile.includes("baseline")
  || profile.includes("main")
  || profile.includes("high");

const fps = eval(stream.r_frame_rate); // "30/1" → 30
const fpsOk = fps <= 30;

const widthOk = stream.width <= 1920;
const heightOk = stream.height <= 1920; // Shorts vertical OK

